const raw = $input.first().json;
const expected = $env.ANSER_WEBHOOK_TOKEN || '';
if (expected && ((raw.headers || {})['x-anser-token'] || '') !== expected) {
  return [{ json: { valid: false, error: 'Unauthorized' } }];
}
const b = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
// 2 đường vào (PDF V2 E2): chụp phiếu cân → OCR (scenario) HOẶC nhập app trực tiếp
const use_ocr = !!b.scenario;
if (!use_ocr && (!b.material_code || !b.qty_kg)) {
  return [{ json: { valid: false, error: 'Missing required fields: material_code, qty_kg (hoặc scenario để OCR phiếu cân)' } }];
}
// harvest_ts: client gửi ISO hoặc harvest_hours_ago (phiếu cân ghi giờ thu hái)
const hoursAgo = Number(b.harvest_hours_ago ?? 5);
const harvest_ts = b.harvest_ts || new Date(Date.now() - hoursAgo * 3600 * 1000).toISOString();
const lot_code = b.lot_code || ('LOT-' + new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-' + Math.random().toString(36).slice(2, 7).toUpperCase());
return [{ json: { valid: true, use_ocr, scenario: b.scenario || null, lot_code, harvest_ts, order_code: b.order_code || null, direct: { farmer: b.farmer || null, region_grown: b.region_grown || null, part: b.part || null, form: b.form || 'tuoi', material_code: b.material_code || null, qty_kg: b.qty_kg || 0, unit_cost_vnd: b.unit_cost_vnd || 0, gacp_cert: b.gacp_cert || null } } }];

// Tiền trả nông hộ = cân × đơn giá — lệch là sai giá vốn NVL → chặn, chờ đối soát
const ocr = $('OCR Weigh Slip (Brain)').first().json;
const val = $input.first().json;
const v = $('Verify Anser Token').first().json;
const line = (ocr.items || [])[0] || {};
const d = { is_valid: val.is_valid === true };
d.intake_body = JSON.stringify({ lot_code: v.lot_code, farmer: ocr.farmer, region_grown: ocr.region_grown, part: ocr.part, form: ocr.form || 'tuoi', material_code: line.sku, qty_kg: line.qty || 0, unit_cost_vnd: line.unit_price || 0, harvest_ts: v.harvest_ts, gacp_cert: ocr.gacp_cert || null, order_code: v.order_code });
d.pending_body = JSON.stringify({ kind: 'material_intake', reason: `Phieu can lech ${val.difference} VND — tien tra nong ho phai khop can x don gia`, ocr_total: val.ocr_total, calculated_total: val.calculated_total, raw_payload: { farmer: ocr.farmer, items: ocr.items } });
return [{ json: d }];

// Nhập app trực tiếp (xưởng không chụp phiếu cân)
const v = $input.first().json;
return [{ json: { intake_body: JSON.stringify({ lot_code: v.lot_code, ...v.direct, harvest_ts: v.harvest_ts, order_code: v.order_code }) } }];

const d = $input.first().json;
const fmt = n => new Intl.NumberFormat('vi-VN').format(n);
const dup = d.deduped === true;
// Cửa sổ chế biến 24h (giữ cynarin): ok 🟢 / urgent 🟠 (<6h) / overdue 🔴 (quá hạn)
let title, color, desc;
if (dup) { title = '🔁 Lô trùng lot_code (bỏ qua)'; color = 10197915; desc = 'Phiếu cân gửi lại — không nhập trùng.'; }
else if (d.window_status === 'overdue') { title = '🔴 QUÁ CỬA SỔ 24H — lô ' + d.lot_code; color = 15158332; desc = 'Nguyên liệu tươi đã ' + (24 - d.hours_left).toFixed(1) + 'h kể từ thu hái — QUÁ HẠN ' + Math.abs(d.hours_left).toFixed(1) + 'h, nguy cơ mất cynarin. Cân nhắc chuyển hướng sản phẩm.'; }
else if (d.window_status === 'urgent') { title = '🟠 KHẨN: đưa vào chế biến ngay — lô ' + d.lot_code; color = 15105570; desc = 'Chỉ còn **' + d.hours_left + 'h** trong cửa sổ 24h giữ dược tính.'; }
else { title = '🌿 Nhập lô nguyên liệu ' + d.lot_code; color = 3066993; desc = d.window_status === 'ok' ? ('Còn ' + d.hours_left + 'h trong cửa sổ chế biến 24h.') : 'Nguyên liệu khô — lưu kho được ≤ 1 năm.'; }
if (d.order_linked) desc += '\n→ Đơn liên quan: **NVL đã về, sẵn sàng sản xuất**';
const notify_body = JSON.stringify({ channel: 'discord', title, color, description: desc, fields: [ { name: 'Nông hộ/HTX', value: String(d.farmer || 'N/A'), inline: true }, { name: 'NVL', value: String(d.material_code || ''), inline: true }, { name: 'Khối lượng', value: fmt(d.qty_kg || 0) + ' kg', inline: true } ] });
const resp = JSON.stringify({ status: d.status, lot_code: d.lot_code, deduped: dup, window_status: d.window_status || null, hours_left: d.hours_left ?? null, order_linked: d.order_linked || false });
return [{ json: { notify_body, resp } }];
